INSERT INTO `posts` VALUES
(478,2,3,4,NULL,'গয়না হাতিয়ে নিতে দাদিকে হত্যা করেন নাতনি','54545454','article','গয়না হাতিয়ে নিতে দাদিকে হত্যা করেন নাতনি',0,1,1,0,1,1,0,NULL,'<div style=\"text-align: justify;\">নাটোরের বড়াইগ্রাম উপজেলায় বৃদ্ধা মমতাজ বেগম (৬৯) হত্যা মামলায় গ্রেপ্তার তাঁর নাতনি ফাউজিয়া খাতুন হত্যাকাণ্ডের দায় স্বীকার করে আদালতে ১৬৪ ধারায় জবানবন্দি দিয়েছেন। জবানবন্দিতে ফাউজিয়া উল্লেখ করেন, দাদির শরীরে থাকা স্বর্ণালংকার হাতিয়ে নেওয়ার উদ্দেশ্যে তাঁকে হত্যা করেন তিনি।</div><div style=\"text-align: justify;\"><br></div><div style=\"text-align: justify;\">আজ বৃহস্পতিবার সন্ধ্যায় নাটোরের সিনিয়র জুডিশিয়াল ম্যাজিস্ট্রেট তৌহিদুল ইসলামের (সুমন) কাছে স্বীকারোক্তিমূলক জবানবন্দি দিয়েছেন ফাউজিয়া। পরে তাঁকে কারাগারে পাঠানোর নির্দেশ দেন আদালত। বড়াইগ্রাম থানার ভারপ্রাপ্ত কর্মকর্তা (ওসি) গোলাম সারওয়ার বিষয়টি প্রথম আলোকে নিশ্চিত করেছেন।</div><div style=\"text-align: justify;\"><br></div><div style=\"text-align: justify;\">নাটোরের বড়াইগ্রাম উপজেলায় বৃদ্ধা মমতাজ বেগম (৬৯) হত্যা মামলায় গ্রেপ্তার তাঁর নাতনি ফাউজিয়া খাতুন হত্যাকাণ্ডের দায় স্বীকার করে আদালতে ১৬৪ ধারায় জবানবন্দি দিয়েছেন। জবানবন্দিতে ফাউজিয়া উল্লেখ করেন, দাদির শরীরে থাকা স্বর্ণালংকার হাতিয়ে নেওয়ার উদ্দেশ্যে তাঁকে হত্যা করেন তিনি।</div><div style=\"text-align: justify;\"><br></div><div style=\"text-align: justify;\">আজ বৃহস্পতিবার সন্ধ্যায় নাটোরের সিনিয়র জুডিশিয়াল ম্যাজিস্ট্রেট তৌহিদুল ইসলামের (সুমন) কাছে স্বীকারোক্তিমূলক জবানবন্দি দিয়েছেন ফাউজিয়া। পরে তাঁকে কারাগারে পাঠানোর নির্দেশ দেন আদালত। বড়াইগ্রাম থানার ভারপ্রাপ্ত কর্মকর্তা (ওসি) গোলাম সারওয়ার বিষয়টি প্রথম আলোকে নিশ্চিত করেছেন।</div>','17600206784I3U9Ado.jpg',NULL,NULL,NULL,NULL,NULL,54,62,0,NULL,0,1,0,'true',71,0,NULL,'2026-03-14 18:27:37','2026-03-14 12:27:37','গয়না হাতিয়ে নিতে দাদিকে হত্যা করেন নাতনি','নাটোরের বড়াইগ্রাম উপজেলায় বৃদ্ধা মমতাজ বেগম (৬৯) হত্যা মামলায় গ্রেপ্তার তাঁর নাতনি ফাউজিয়া খাতুন হত্যাকাণ্ডের দায় স্বীকার করে আদালতে ১৬৪ ধারায় জবানবন্দি দিয়েছেন। জবানবন্দিতে ফাউজিয়া উল্লেখ করেন, দাদির শরীরে থাকা স্বর্ণালংকার হাতিয়ে নেওয়ার উদ্দেশ্যে তাঁকে হত্যা করেন তিনি।'),
(479,2,3,2,NULL,'মানবতাবিরোধী অপরাধ: হাসানুল হক ইনুর বিরুদ্ধে আনুষ্ঠানিক অভিযোগ দাখিল','মানবতাবিরোধী-অপরাধ:-হাসানুল-হক-ইনুর-বিরুদ্ধে-আনুষ্ঠানিক-অভিযোগ-দাখিল','article','মানবতাবিরোধী অপরাধ: হাসানুল হক ইনুর বিরুদ্ধে আনুষ্ঠানিক অভিযোগ দাখিল',0,1,1,0,1,1,0,NULL,'<div style=\"text-align: justify;\">জুলাই গণ-অভ্যুত্থানের সময় সংঘটিত মানবতাবিরোধী অপরাধের ঘটনায় জাতীয় সমাজতান্ত্রিক দলের (জাসদ) সভাপতি হাসানুল হক ইনুর বিরুদ্ধে আনুষ্ঠানিক অভিযোগ (ফরমাল চার্জ) দাখিল করা হয়েছে।</div><div style=\"text-align: justify;\"><br></div><div style=\"text-align: justify;\">আজ বৃহস্পতিবার আন্তর্জাতিক অপরাধ ট্রাইব্যুনাল-২-এ এই আনুষ্ঠানিক অভিযোগ দাখিল করে প্রসিকিউশন। আনুষ্ঠানিক অভিযোগ ৩৯ পৃষ্ঠার। এতে ২০ জনকে সাক্ষী রাখা হয়েছে।</div><div style=\"text-align: justify;\"><br></div><div style=\"text-align: justify;\">পরে বিচারপতি নজরুল ইসলাম চৌধুরীর নেতৃত্বে তিন সদস্যের ট্রাইব্যুনাল-২ এই আনুষ্ঠানিক অভিযোগ আমলে নেন। এই ট্রাইব্যুনালের অপর দুই সদস্য হলেন বিচারক মো. মঞ্জুরুল বাছিদ ও বিচারক নূর মোহাম্মদ শাহরিয়ার।জুলাই গণ-অভ্যুত্থানের সময় সংঘটিত মানবতাবিরোধী অপরাধের ঘটনায় জাতীয় সমাজতান্ত্রিক দলের (জাসদ) সভাপতি হাসানুল হক ইনুর বিরুদ্ধে আনুষ্ঠানিক অভিযোগ (ফরমাল চার্জ) দাখিল করা হয়েছে।</div><div style=\"text-align: justify;\"><br></div><div style=\"text-align: justify;\">আজ বৃহস্পতিবার আন্তর্জাতিক অপরাধ ট্রাইব্যুনাল-২-এ এই আনুষ্ঠানিক অভিযোগ দাখিল করে প্রসিকিউশন। আনুষ্ঠানিক অভিযোগ ৩৯ পৃষ্ঠার। এতে ২০ জনকে সাক্ষী রাখা হয়েছে।</div><div style=\"text-align: justify;\"><br></div><div style=\"text-align: justify;\">পরে বিচারপতি নজরুল ইসলাম চৌধুরীর নেতৃত্বে তিন সদস্যের ট্রাইব্যুনাল-২ এই আনুষ্ঠানিক অভিযোগ আমলে নেন। এই ট্রাইব্যুনালের অপর দুই সদস্য হলেন বিচারক মো. মঞ্জুরুল বাছিদ ও বিচারক নূর মোহাম্মদ শাহরিয়ার।জুলাই গণ-অভ্যুত্থানের সময় সংঘটিত মানবতাবিরোধী অপরাধের ঘটনায় জাতীয় সমাজতান্ত্রিক দলের (জাসদ) সভাপতি হাসানুল হক ইনুর বিরুদ্ধে আনুষ্ঠানিক অভিযোগ (ফরমাল চার্জ) দাখিল করা হয়েছে।</div><div style=\"text-align: justify;\"><br></div><div style=\"text-align: justify;\">আজ বৃহস্পতিবার আন্তর্জাতিক অপরাধ ট্রাইব্যুনাল-২-এ এই আনুষ্ঠানিক অভিযোগ দাখিল করে প্রসিকিউশন। আনুষ্ঠানিক অভিযোগ ৩৯ পৃষ্ঠার। এতে ২০ জনকে সাক্ষী রাখা হয়েছে।</div><div style=\"text-align: justify;\"><br></div><div style=\"text-align: justify;\">পরে বিচারপতি নজরুল ইসলাম চৌধুরীর নেতৃত্বে তিন সদস্যের ট্রাইব্যুনাল-২ এই আনুষ্ঠানিক অভিযোগ আমলে নেন। এই ট্রাইব্যুনালের অপর দুই সদস্য হলেন বিচারক মো. মঞ্জুরুল বাছিদ ও বিচারক নূর মোহাম্মদ শাহরিয়ার।জুলাই গণ-অভ্যুত্থানের সময় সংঘটিত মানবতাবিরোধী অপরাধের ঘটনায় জাতীয় সমাজতান্ত্রিক দলের (জাসদ) সভাপতি হাসানুল হক ইনুর বিরুদ্ধে আনুষ্ঠানিক অভিযোগ (ফরমাল চার্জ) দাখিল করা হয়েছে।</div><div style=\"text-align: justify;\"><br></div><div style=\"text-align: justify;\">আজ বৃহস্পতিবার আন্তর্জাতিক অপরাধ ট্রাইব্যুনাল-২-এ এই আনুষ্ঠানিক অভিযোগ দাখিল করে প্রসিকিউশন। আনুষ্ঠানিক অভিযোগ ৩৯ পৃষ্ঠার। এতে ২০ জনকে সাক্ষী রাখা হয়েছে।</div><div style=\"text-align: justify;\"><br></div><div style=\"text-align: justify;\">পরে বিচারপতি নজরুল ইসলাম চৌধুরীর নেতৃত্বে তিন সদস্যের ট্রাইব্যুনাল-২ এই আনুষ্ঠানিক অভিযোগ আমলে নেন। এই ট্রাইব্যুনালের অপর দুই সদস্য হলেন বিচারক মো. মঞ্জুরুল বাছিদ ও বিচারক নূর মোহাম্মদ শাহরিয়ার।</div>','17600209421hGY9U3u.jpg',NULL,NULL,NULL,NULL,NULL,55,66,0,NULL,0,1,0,'true',67,0,NULL,'2026-03-08 10:37:46','2026-03-08 04:37:46','মানবতাবিরোধী অপরাধ: হাসানুল হক ইনুর বিরুদ্ধে আনুষ্ঠানিক অভিযোগ দাখিল','জুলাই গণ-অভ্যুত্থানের সময় সংঘটিত মানবতাবিরোধী অপরাধের ঘটনায় জাতীয় সমাজতান্ত্রিক দলের (জাসদ) সভাপতি হাসানুল হক ইনুর বিরুদ্ধে আনুষ্ঠানিক অভিযোগ (ফরমাল চার্জ) দাখিল করা হয়েছে।'),
(480,2,7,NULL,NULL,'চকরিয়ার বাসা থেকে স্কুলছাত্রীকে অপহরণ, রোহিঙ্গা শিবির থেকে উদ্ধার','5445458','article','চকরিয়ার বাসা থেকে স্কুলছাত্রীকে অপহরণ, রোহিঙ্গা শিবির থেকে উদ্ধার',0,1,1,0,1,1,0,NULL,'<div style=\"text-align: justify;\">কক্সবাজারের চরকিয়ার পৌরসভার একটি বাসা থেকে অপহরণের শিকার তৃতীয় শ্রেণির এক স্কুলছাত্রীকে উখিয়া উপজেলার কুতুপালং রোহিঙ্গা শিবির থেকে উদ্ধার করেছে পুলিশ। গতকাল বুধবার রাতে ওই ছাত্রীকে উদ্ধার করা হয়। এর আগে গত মঙ্গলবার শিক্ষকের কাছে প্রাইভেট পড়তে গিয়ে আর বাড়িতে ফেরেনি ওই ছাত্রী। ছাত্রীকে উদ্ধার করা হলেও তার অপহরণকারীকে আটক করতে পারেনি পুলিশ।</div><div style=\"text-align: justify;\"><br></div><div style=\"text-align: justify;\">গতকাল রাত ১১টার দিকে অপহৃত ছাত্রীকে উদ্ধারের পর চকরিয়া থানায় আনা হয় বলে জানান অভিযানে নেতৃত্ব দেওয়া চকরিয়া থানার উপপরিদর্শক (এসআই) জাকির হোসেন। তিনি প্রথম আলোকে বলেন, ওই ছাত্রীর অপহরণকারী একজন রোহিঙ্গা যুবক। অন্য এক রোহিঙ্গা নারীকে বিয়ে করে চকরিয়া পৌরশহরে বাসা ভাড়া নিয়ে থাকতেন। সেই বাসায় অপহৃত ছাত্রীকে প্রাইভেট পড়াতেন তিনি। ওই রোহিঙ্গা যুবক বাংলাদেশের ভুয়া জাতীয় পরিচয়পত্র ব্যবহার করতেন বলে জানা গেছে।কক্সবাজারের চরকিয়ার পৌরসভার একটি বাসা থেকে অপহরণের শিকার তৃতীয় শ্রেণির এক স্কুলছাত্রীকে উখিয়া উপজেলার কুতুপালং রোহিঙ্গা শিবির থেকে উদ্ধার করেছে পুলিশ। গতকাল বুধবার রাতে ওই ছাত্রীকে উদ্ধার করা হয়। এর আগে গত মঙ্গলবার শিক্ষকের কাছে প্রাইভেট পড়তে গিয়ে আর বাড়িতে ফেরেনি ওই ছাত্রী। ছাত্রীকে উদ্ধার করা হলেও তার অপহরণকারীকে আটক করতে পারেনি পুলিশ।</div><div style=\"text-align: justify;\"><br></div><div style=\"text-align: justify;\">গতকাল রাত ১১টার দিকে অপহৃত ছাত্রীকে উদ্ধারের পর চকরিয়া থানায় আনা হয় বলে জানান অভিযানে নেতৃত্ব দেওয়া চকরিয়া থানার উপপরিদর্শক (এসআই) জাকির হোসেন। তিনি প্রথম আলোকে বলেন, ওই ছাত্রীর অপহরণকারী একজন রোহিঙ্গা যুবক। অন্য এক রোহিঙ্গা নারীকে বিয়ে করে চকরিয়া পৌরশহরে বাসা ভাড়া নিয়ে থাকতেন। সেই বাসায় অপহৃত ছাত্রীকে প্রাইভেট পড়াতেন তিনি। ওই রোহিঙ্গা যুবক বাংলাদেশের ভুয়া জাতীয় পরিচয়পত্র ব্যবহার করতেন বলে জানা গেছে।কক্সবাজারের চরকিয়ার পৌরসভার একটি বাসা থেকে অপহরণের শিকার তৃতীয় শ্রেণির এক স্কুলছাত্রীকে উখিয়া উপজেলার কুতুপালং রোহিঙ্গা শিবির থেকে উদ্ধার করেছে পুলিশ। গতকাল বুধবার রাতে ওই ছাত্রীকে উদ্ধার করা হয়। এর আগে গত মঙ্গলবার শিক্ষকের কাছে প্রাইভেট পড়তে গিয়ে আর বাড়িতে ফেরেনি ওই ছাত্রী। ছাত্রীকে উদ্ধার করা হলেও তার অপহরণকারীকে আটক করতে পারেনি পুলিশ।</div><div style=\"text-align: justify;\"><br></div><div style=\"text-align: justify;\">গতকাল রাত ১১টার দিকে অপহৃত ছাত্রীকে উদ্ধারের পর চকরিয়া থানায় আনা হয় বলে জানান অভিযানে নেতৃত্ব দেওয়া চকরিয়া থানার উপপরিদর্শক (এসআই) জাকির হোসেন। তিনি প্রথম আলোকে বলেন, ওই ছাত্রীর অপহরণকারী একজন রোহিঙ্গা যুবক। অন্য এক রোহিঙ্গা নারীকে বিয়ে করে চকরিয়া পৌরশহরে বাসা ভাড়া নিয়ে থাকতেন। সেই বাসায় অপহৃত ছাত্রীকে প্রাইভেট পড়াতেন তিনি। ওই রোহিঙ্গা যুবক বাংলাদেশের ভুয়া জাতীয় পরিচয়পত্র ব্যবহার করতেন বলে জানা গেছে।</div>','1760070508iAyoJMoA.jpg',NULL,NULL,NULL,NULL,NULL,54,62,0,NULL,0,1,0,'true',75,0,NULL,'2026-03-14 18:25:30','2026-03-14 12:25:30','চকরিয়ার বাসা থেকে স্কুলছাত্রীকে অপহরণ, রোহিঙ্গা শিবির থেকে উদ্ধার','চকরিয়ার বাসা থেকে স্কুলছাত্রীকে অপহরণ, রোহিঙ্গা শিবির থেকে উদ্ধার'),
(481,2,3,2,NULL,'রাজধানীর নিউমার্কেট ও পল্লবী এলাকায় পুলিশের বিশেষ অভিযান, গ্রেপ্তার ৩০','6556564','article','রাজধানীর নিউমার্কেট ও পল্লবী এলাকায় পুলিশের বিশেষ অভিযান, গ্রেপ্তার ৩০',0,1,1,0,1,1,0,NULL,'<div>রাজধানীর নিউমার্কেট ও পল্লবী এলাকায় গতকাল বুধবার দিনভর বিশেষ অভিযান চালিয়ে বিভিন্ন অপরাধে জড়িত থাকার অভিযোগে ৩০ জনকে গ্রেপ্তার করেছে ঢাকা মহানগর পুলিশ (ডিএমপি)। এ সময় তাঁদের কাছ থেকে বিপুল পরিমাণ মাদক ও মাদক বিক্রির দুই লাখ ৯২ হাজার ৯৯০ টাকা উদ্ধার করা হয়েছে।</div><div>আজ বৃহস্পতিবার ডিএমপির এক সংবাদ বিজ্ঞপ্তিতে এ তথ্য জানানো হয়। গ্রেপ্তার ব্যক্তিরা হলেন— মো. সজল মিয়া (৪২), মো. বজলু (৩৯), মো. জহির (৪০), মো. মনির হোসেন (৩৮), মো. ইউসুফ (৩৯), মো. হবিবুর রহমান (৪০), আশরাফুল ইসলাম (১৯), মো. সাহাবুদ্দিন (৪০), মো. মহিউদ্দিন (২২), মো. আরমান (৩০), মো. শাকিল (২০), মো. সুজন (২৫), মো. নাহিদ হাসান (২৪), মো. কাওসার (১৮), মো. জাহিদ (২২), মো. রিয়াজ (১৯), মো. আবদুল করিম (২০), স্বপন হোসেন (৩৫), মো. নবাব (২২), মো. সোহেল (২০), মো. রফিক (২৩), মো. কবির আহমেদ (২০), মো. আরিফ (২১), মো. খাইরুল ইসলাম (২০), বিশাদ হাসান (২৩), মো. শাকিল, মো. সোহান আহম্মেদ (২২), মো. তুষার খান (২৫) ও মো. হাফিজুল ইসলাম (২২)।</div><div><br></div><div>এঁদের মধ্যে নিউমার্কেট থানা–পুলিশ ৯ জন এবং পল্লবী থানা-পুলিশ ২১ জনকে গ্রেপ্তার করে। গ্রেপ্তার ব্যক্তিরা নিয়মিত মামলা, পরোয়ানাভুক্ত আসামি ও বিভিন্ন অপরাধে জড়িত বলে ডিএমপির সংবাদ বিজ্ঞপ্তিতে জানানো হয়েছে।রাজধানীর নিউমার্কেট ও পল্লবী এলাকায় গতকাল বুধবার দিনভর বিশেষ অভিযান চালিয়ে বিভিন্ন অপরাধে জড়িত থাকার অভিযোগে ৩০ জনকে গ্রেপ্তার করেছে ঢাকা মহানগর পুলিশ (ডিএমপি)। এ সময় তাঁদের কাছ থেকে বিপুল পরিমাণ মাদক ও মাদক বিক্রির দুই লাখ ৯২ হাজার ৯৯০ টাকা উদ্ধার করা হয়েছে।</div><div>আজ বৃহস্পতিবার ডিএমপির এক সংবাদ বিজ্ঞপ্তিতে এ তথ্য জানানো হয়। গ্রেপ্তার ব্যক্তিরা হলেন— মো. সজল মিয়া (৪২), মো. বজলু (৩৯), মো. জহির (৪০), মো. মনির হোসেন (৩৮), মো. ইউসুফ (৩৯), মো. হবিবুর রহমান (৪০), আশরাফুল ইসলাম (১৯), মো. সাহাবুদ্দিন (৪০), মো. মহিউদ্দিন (২২), মো. আরমান (৩০), মো. শাকিল (২০), মো. সুজন (২৫), মো. নাহিদ হাসান (২৪), মো. কাওসার (১৮), মো. জাহিদ (২২), মো. রিয়াজ (১৯), মো. আবদুল করিম (২০), স্বপন হোস