(581,1,NULL,NULL,NULL,'The Italian village with the \'elixir\' of healthy life','The-Italian-village-with-the-\'elixir\'-of-healthy-life','rss',NULL,0,0,0,0,0,0,0,NULL,'It\'s a place of terraced lemon groves, a paradoxically warm mountain breeze, and a powerful fat-killing gene carried by a few lucky residents.',NULL,'https://cdn.cnn.com/cnnnext/dam/assets/221007091932-01-body-limone-sul-garda-super-169.jpg',NULL,NULL,NULL,NULL,26,NULL,0,NULL,0,1,0,'true',0,0,'https://www.cnn.com/travel/article/limone-sul-garda-italy-elixir-wellness/index.html','2026-01-14 01:28:00','2026-01-14 01:28:00',NULL,NULL),
(582,1,NULL,NULL,NULL,'Virgin Boeing 747 to launch rocket into space','Virgin-Boeing-747-to-launch-rocket-into-space','rss',NULL,0,0,0,0,0,0,0,NULL,'At the far southwestern tip of England, dangling into the Atlantic, the remote region of Cornwall rarely feels like the center of the world.',NULL,'https://cdn.cnn.com/cnnnext/dam/assets/221019093528-01b-uk-spaceport-747-super-169.jpg',NULL,NULL,NULL,NULL,26,NULL,0,NULL,0,1,0,'true',0,0,'https://www.cnn.com/travel/article/virgin-orbit-boeing-747-newquay-scn/index.html','2026-01-14 01:28:00','2026-01-14 01:28:00',NULL,NULL),
(583,1,NULL,NULL,NULL,'The hunt for the world\'s most elusive shipwrecks','The-hunt-for-the-world\'s-most-elusive-shipwrecks','rss',NULL,0,0,0,0,0,0,0,NULL,'In March 2022, the world let out a collective gasp when the remarkably preserved shipwreck of Ernest Shackleton\'s HMS Endurance was discovered almost two miles beneath the icy Antarctic seas.',NULL,'https://cdn.cnn.com/cnnnext/dam/assets/221019113556-uss-ind-tz-1-super-169.jpg',NULL,NULL,NULL,NULL,26,NULL,0,NULL,0,1,0,'true',0,0,'https://www.cnn.com/travel/article/famous-missing-shipwrecks-cmd/index.html','2026-01-14 01:28:00','2026-01-14 01:28:00',NULL,NULL),
(584,1,NULL,NULL,NULL,'Secrets from the world\'s toughest dining scene','Secrets-from-the-world\'s-toughest-dining-scene','rss',NULL,0,0,0,0,0,0,0,NULL,'Hong Kong is widely considered one of the most challenging cities in the world to operate a restaurant -- a roiling cauldron of changing tastes, cleaver-sharp competition and unsavory economics.',NULL,'https://cdn.cnn.com/cnnnext/dam/assets/220927101334-06-geoffrey-wu-hong-kong-toughest-tables-chaat-super-169.jpg',NULL,NULL,NULL,NULL,26,NULL,0,NULL,0,1,0,'true',0,0,'https://www.cnn.com/travel/article/geoffrey-wu-hong-kong-toughest-tables/index.html','2026-01-14 01:28:00','2026-01-14 01:28:00',NULL,NULL),
